if(EditorApplication.isPlaying)throw new System.Exception("Edit only");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();string D="ArtSource/Pipeline/Review/BriarwickEnvironment05Revision01";var root=GameObject.Find("Revision01 - regional terrain and detail coverage");var group=root.transform.Find("ForestEdges");if(group.childCount>0)throw new System.Exception("Already populated");
var terrain=Terrain.activeTerrain;var td=terrain.terrainData;float Y(float x,float z){return terrain.SampleHeight(new Vector3(x,0,z))+terrain.transform.position.y;}float Creek(float x){return -68+6*Mathf.Sin(x/26)+.025f*x;}float S(float a,float b,float v){return Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,v));}float Slope(Vector2 p){return td.GetSteepness((p.x-terrain.transform.position.x)/320,(p.y-terrain.transform.position.z)/320);}bool OldGrove(Vector2 p){return p.x> -63&&p.x<8&&p.y>43&&p.y<142;}
var layout=Newtonsoft.Json.Linq.JObject.Parse(System.IO.File.ReadAllText("ArtSource/Pipeline/Review/BriarwickHamletDev01/Layout.json"));var road=new System.Collections.Generic.List<Vector3>();foreach(var r in layout["routes"]){float half=(float)r["widthMetres"]*.5f;foreach(var q in r["points"])road.Add(new Vector3((float)q[0],(float)q[2],half));}float Road(Vector2 p){float best=999;foreach(var q in road){float dx=q.x-p.x,dz=q.y-p.y;float d=Mathf.Sqrt(dx*dx+dz*dz)-q.z;if(d<best)best=d;}return best;}
Bounds BoundsOf(GameObject go){var rr=go.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.gameObject.layer!=2).ToArray();if(rr.Length==0)return new Bounds(Vector3.zero,Vector3.zero);var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return b;}
var structures=new System.Collections.Generic.List<Bounds>();foreach(var g in scene.GetRootGameObjects().Where(g=>g.activeInHierarchy&&(g.name.Contains("architectural review")||g.name=="Stable A - rural thatch review03"))){var b=BoundsOf(g);if(b.size.sqrMagnitude>0)structures.Add(b);}foreach(Transform t in GameObject.Find("03 Eleven primary building locations").transform){var b=BoundsOf(t.gameObject);if(b.size.sqrMagnitude>0)structures.Add(b);}var plots=GameObject.Find("04 Common gardens farming and graveyard").GetComponentsInChildren<MeshRenderer>().Select(r=>r.bounds).ToArray();bool InBounds(Vector2 p,Bounds b,float extra){return p.x>=b.min.x-extra&&p.x<=b.max.x+extra&&p.y>=b.min.z-extra&&p.y<=b.max.z+extra;}bool Reserved(Vector2 p,float extra){return structures.Any(b=>InBounds(p,b,extra))||plots.Any(b=>InBounds(p,b,extra));}
bool Safe(Vector2 p,float radius){return p.x> -153&&p.x<153&&p.y> -163&&p.y<143&&!OldGrove(p)&&!Reserved(p,radius+1)&&Road(p)>radius+1.15f&&Mathf.Abs(p.y-Creek(p.x))>3.5f+radius&&Y(p.x,p.y)>4.15f&&Slope(p)<30;}
string Region(Vector2 p){if(Mathf.Abs(p.y-Creek(p.x))<13)return "CreekBanks";if(Mathf.Abs(p.x)<80&&p.y> -55&&p.y<48)return "VillageMargins";if(p.x> -82&&p.x<27&&p.y>35)return "WoodlandSkirts";if(Mathf.Abs(p.x)>126||p.y< -135||p.y>126)return "DistantCountryside";if(Mathf.Abs(p.x)>87||Slope(p)>8||p.y>100)return "Hillsides";return "Meadows";}

var proxy=GameObject.Find("Woodland03_Remainder_Canopy").GetComponent<MeshFilter>();var ids=proxy.sharedMesh.triangles.Select(i=>i/10).Distinct().OrderBy(i=>i).ToArray();var vv=proxy.sharedMesh.vertices;var existing=UnityEngine.Object.FindObjectsByType<CapsuleCollider>(FindObjectsSortMode.None).Where(c=>c.gameObject.name.Contains("Tree")).Select(c=>new Vector2(c.transform.position.x,c.transform.position.z)).ToList();var records=new List<object>();var rng=new System.Random(50942);int[] types={1,4,6,8};int added=0,covered=0;foreach(int id in ids){var at=proxy.transform.TransformPoint(vv[id*10]);var p=new Vector2(at.x,at.z);if(existing.Any(q=>(p-q).sqrMagnitude<36)){covered++;records.Add(new{id,x=p.x,z=p.y,status="Existing approved real tree within 6m"});continue;}var original=p;bool valid=false;for(int attempt=0;attempt<49;attempt++){if(attempt>0){float angle=attempt*2.4f;float r=.5f+attempt*.17f;p=original+new Vector2(Mathf.Cos(angle),Mathf.Sin(angle))*r;}if(!Reserved(p,4.2f)&&Road(p)>5.2f&&Mathf.Abs(p.y-Creek(p.x))>8&&Slope(p)<34&&Y(p.x,p.y)>4.2f&&!existing.Any(q=>(p-q).sqrMagnitude<36)){valid=true;break;}}if(!valid)throw new System.Exception("Unsafe tree position "+id);int type=types[id%4];var src=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/BlightBloom/Art/Environment/Briarwick/Woodland01/Prefabs/BW_Woodland01_Tree"+type+".prefab");var g=(GameObject)PrefabUtility.InstantiatePrefab(src);g.name="Revision01_Tree_Proxy"+id+"_Type"+type;g.transform.SetParent(group,false);float scale=.78f+(float)rng.NextDouble()*.32f;g.transform.SetPositionAndRotation(new Vector3(p.x,Y(p.x,p.y),p.y),Quaternion.Euler(0,(float)rng.NextDouble()*360,0));g.transform.localScale=Vector3.one*scale;var rr=g.GetComponent<Renderer>();var mats=rr.sharedMaterials;for(int i=0;i<mats.Length;i++)if(mats[i].name.Contains("Leaves"))mats[i]=AssetDatabase.LoadAssetAtPath<Material>("Assets/BlightBloom/Art/Environment/Briarwick/Woodland03/Materials/"+mats[i].name.Replace("Woodland01","Woodland03")+".mat");rr.sharedMaterials=mats;PrefabUtility.RecordPrefabInstancePropertyModifications(rr);var m=g.GetComponent<MeshFilter>().sharedMesh;var v=m.vertices;var bark=m.GetTriangles(0).Distinct().ToArray();float low=bark.Min(i=>v[i].y);float high=bark.Where(i=>v[i].y<low+.08f).Select(i=>g.transform.TransformPoint(v[i])).Max(q=>q.y-Y(q.x,q.z));if(high>.03f)g.transform.position-=Vector3.up*(high+.015f);PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);existing.Add(p);added++;records.Add(new{id,type,x=p.x,z=p.y,shift=Vector2.Distance(original,p),scale,status="New real tree"});}
proxy.gameObject.SetActive(false);GameObject.Find("Woodland03_Remainder_Trunks").SetActive(false);Physics.SyncTransforms();UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);var report=new{proxyPairs=ids.Length,newTrees=added,coveredByExistingTree=covered,addedTriangles=group.GetComponentsInChildren<MeshFilter>().Sum(f=>f.sharedMesh.triangles.Length/3),records};System.IO.File.WriteAllText(D+"/TreeReplacement.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return new{report.proxyPairs,report.newTrees,report.coveredByExistingTree,report.addedTriangles};
